SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, MIN(amount) OVER (PARTITION BY merchant ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_amount, MAX(amount) OVER (PARTITION BY merchant ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_amount, AVG(amount) OVER (PARTITION BY merchant ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_amount, NTILE(3) OVER (PARTITION BY txn_type ORDER BY amount, id) AS amount_bucket FROM transactions;
